/// <summary>
/// Example UPSPricingAttribute of table <c>RetailInventTable</c> field dateToBeBlocked.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeRetailInventTableDateToBeBlocked extends UPSPricingAttributeRetailInventTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(RetailInventTable, dateToBeBlocked);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::Date);
    RetailInventTable retailInventTable;
    while select dateToBeBlocked from retailInventTable
        group by dateToBeBlocked
    {
        ret.add(retailInventTable.dateToBeBlocked);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(RetailInventTable, dateToBeBlocked));
    qbr.value(queryValue(_value));
}
